{
  "title": "The Glass Diver's Escape",
  "gate_token": "pYrWzhw5B7qd9d0_G9XyjQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city looms under a smoky sky.",
      "visual_description": "Crumbling castle gates stand open, old royal banners torn and flapping in wind. Dust and ash drift through empty streets.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "A glowing eye flickers in a broken tower window.",
      "visual_description": "High in a cursed tower, the oracle lamp's flame casts a single eye-shaped light, scanning the ruins below.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The mapmaker marks danger zones on her chart.",
      "visual_description": "Mara the cartographer kneels by a collapsed fountain, inking X's on a parchment while the tin fox watches nearby.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Patrols of armored figures march in silence.",
      "visual_description": "A line of faceless armored figures clanks along a boulevard, their visors dark, ignoring the frightened townspeople cowering in shadows.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver peers into a reflecting pool.",
      "visual_description": "Glass diver kneels before a cracked pool, his helmet reflecting the broken city lights and a faint image of a hidden passage.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "A magic door sealed with shifting symbols bars the way.",
      "visual_description": "A tall door of dark wood pulses with glowing runes that slide like snakes, blocking the path to the inner city.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox scurries under a collapsed archway.",
      "visual_description": "Tin fox squeezes through rubble, its key-wind tail ticking, emerging into a courtyard filled with old royal banners.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara deciphers a carved clue on a broken pillar.",
      "visual_description": "Mara traces her ink-stained fingers over a stone pillar carved with old trade routes, while the oracle lamp hovers nearby casting light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector snores on a pile of ledgers.",
      "visual_description": "In a collapsed treasury, the sleeping tax collector lies with a ledger under his head, stamped papers stuck to his sleeves, oblivious to the rescue.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Warnings echo from the lamp's flame.",
      "visual_description": "Oracle lamp flickers, its one eye darting, whispering of a cursed tower that shifts its windows at dusk.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through a mirror into a locked chamber.",
      "visual_description": "Glass diver presses his helmet against a cracked mirror, then passes through like water, emerging in a dusty room filled with scattered keys.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols close in from two streets.",
      "visual_description": "Two lines of armored figures march from opposite directions, their footsteps echoing, as the group hides behind an overturned cart.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox triggers a hidden lever behind a banner.",
      "visual_description": "Tin fox noses aside a frayed royal banner, revealing a brass lever that it pulls with its teeth, causing a stone door to grind open.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "A bridge of crumbling stone spans a chasm ahead.",
      "visual_description": "The bridge is narrow, missing railings, and stretches over a dark gorge; old royal banners hang from broken posts along its length.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector is carried across the bridge.",
      "visual_description": "Glass diver and tin fox drag the sleeping tax collector onto the bridge, while Mara watches for patrols and the lamp casts a wavering light.",
      "characters": ["sleeping_tax_collector", "glass_diver", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge begins to crack under their weight.",
      "visual_description": "A large crack spiders across the stone, sending small rocks tumbling into the darkness below, as the group hurries forward.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The last armored figure blocks the bridge's end.",
      "visual_description": "A single armored figure stands at the far end of the bridge, sword drawn, as the group approaches with the glass diver leading.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes into the mist beyond the bridge.",
      "visual_description": "The bridge collapses behind them as they step onto solid ground, the ruined city fading into fog, with the glass diver's helmet still reflecting its broken lights.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    }
  ]
}

